import{_ as t}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as n,o as i,af as o}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const f=JSON.parse(`{"title":"Reasoning Models and Test-Time Compute (Bridge)","description":"Letting the model think longer' is a performance axis alongside model scale — this page gives app engineers positional sense: thinking and acting are two kinds of spend (when to use a reasoning model vs an agent loop), latency structure, billing, and stop conditions; training-side mechanics bridge to Learn LLM.","frontmatter":{"title":"Reasoning Models and Test-Time Compute (Bridge)","description":"Letting the model think longer' is a performance axis alongside model scale — this page gives app engineers positional sense: thinking and acting are two kinds of spend (when to use a reasoning model vs an agent loop), latency structure, billing, and stop conditions; training-side mechanics bridge to Learn LLM.","domain":"tech","tags":["tech","reasoning","test-time-compute","bridge"],"navOrder":92,"topicId":"reasoning-ttc","layer":"9","status":"bridge","nodeType":"boundary","owner":"learn-ai","externalOwners":[{"site":"llm","url":"https://llm.zenheart.site/"}],"lastVerified":"2026-09-01","bilingualParity":"exact","listed":true},"headers":[],"relativePath":"tech/09-advanced/reasoning-ttc.md","filePath":"tech/09-advanced/reasoning-ttc.md","lastUpdated":1791113340000}`),a={name:"tech/09-advanced/reasoning-ttc.md"};function r(s,e,d,l,g,c){return i(),n("div",null,[...e[0]||(e[0]=[o('<blockquote><p><strong>Group</strong>: Advanced (bridge) | <strong>Previous group exit</strong>: run long-term with release gates and versioning | <strong>This page exit</strong>: know which engineering decision this topic affects, and when to go to Learn LLM</p></blockquote><h1 id="reasoning-models-and-test-time-compute-bridge" tabindex="-1">Reasoning Models and Test-Time Compute (Bridge) <a class="header-anchor" href="#reasoning-models-and-test-time-compute-bridge" aria-label="Permalink to &quot;Reasoning Models and Test-Time Compute (Bridge)&quot;">​</a></h1><blockquote><p><strong>Bridge page</strong>: the training mechanics of reasoning models (the o1/R1 line) — long chain-of-thought RL, GRPO, verifiable rewards — are derived in <a href="https://llm.zenheart.site/" target="_blank" rel="noreferrer">Learn LLM</a> (Chapter 10 · Post-training; inference-side budgets in Chapter 9). This repo keeps only the application-side positional sense: <strong>it is a new consumable, and you decide when to buy it, how much, and how to stop.</strong></p></blockquote><h2 id="_1-overview" tabindex="-1">1. Overview <a class="header-anchor" href="#_1-overview" aria-label="Permalink to &quot;1. Overview&quot;">​</a></h2><p><strong>What problem it solves</strong>: traditional scaling spends money at training time (bigger models); test-time compute spends it at inference — repeated sampling, search, longer thinking — buying higher per-request quality. Reasoning models productize this axis: the same model, the longer it thinks (more reasoning tokens), the higher the average quality.</p><p><strong>Why app engineers need positional sense</strong>: this is not &quot;switch to a stronger model&quot; — it adds a <strong>runtime-tunable budget parameter</strong>. It directly changes three things: the trade space of model selection (small model thinking longer vs large model answering directly), the unit cost structure (billed by amount of thinking), and the product interaction contract (latency and stop conditions).</p><h2 id="_2-usage" tabindex="-1">2. Usage <a class="header-anchor" href="#_2-usage" aria-label="Permalink to &quot;2. Usage&quot;">​</a></h2><h3 id="thinking-and-acting-are-two-kinds-of-spend" tabindex="-1">Thinking and acting are two kinds of spend <a class="header-anchor" href="#thinking-and-acting-are-two-kinds-of-spend" aria-label="Permalink to &quot;Thinking and acting are two kinds of spend&quot;">​</a></h3><p>A reasoning model&#39;s &quot;thinking&quot; (extended inference inside the model) and an agent&#39;s &quot;action loop&quot; (calling tools, observing, deciding again) are <strong>two different quality levers</strong> — both spend inference budget, but they are not interchangeable:</p><table tabindex="0"><thead><tr><th>Lever</th><th>Where it spends</th><th>Good at</th><th>Not good at</th></tr></thead><tbody><tr><td>Thinking (reasoning / TTC)</td><td>reasoning tokens within one call</td><td>problems solvable &quot;in its head&quot;: math, planning, code logic, multi-constraint trade-offs</td><td>needs new facts (→ retrieval) or needs to change external state (→ tools)</td></tr><tr><td>Action loop (agent loop)</td><td>multiple calls + tool execution</td><td>interacting with the external world: querying data, mutating systems, long flows</td><td>closed-form reasoning problems — costlier and slower than thinking</td></tr></tbody></table><p>Selection order: <strong>if it can be thought through in one pass, do not start a loop; loops that need new information or side effects cannot be replaced by thinking.</strong> They can compose (short thinking before each action step), but each layer needs its own budget and stop condition.</p><h3 id="three-direct-product-impacts" tabindex="-1">Three direct product impacts <a class="header-anchor" href="#three-direct-product-impacts" aria-label="Permalink to &quot;Three direct product impacts&quot;">​</a></h3><ol><li><strong>Latency structure</strong>: thinking time varies with difficulty and can be very long — time-to-first-token is no longer controllable. Either surface an explicit &quot;thinking&quot; state in the interaction, or cap the thinking.</li><li><strong>Billing</strong>: reasoning tokens are a real cost item, and the model decides the amount — cost shifts from &quot;per request&quot; to &quot;per request × amount of thinking&quot;; budget circuit breakers (→ <a href="./../08-production/cost-performance.html">Cost and Performance</a>) go from optional to mandatory.</li><li><strong>Stop conditions</strong>: when to cut off thinking is a product decision — timeout, token cap, or budget-forcing-style mechanisms. A thinking call without a stop condition will burn money unboundedly on pathological inputs.</li></ol><h2 id="_3-principles" tabindex="-1">3. Principles <a class="header-anchor" href="#_3-principles" aria-label="Permalink to &quot;3. Principles&quot;">​</a></h2><p>(Deliberately minimal: training and scaling-law derivations belong to Learn LLM.)</p><p>One-line route: repeated sampling raises coverage (more samples solve more problems, but a verifier is needed to cash in) → allocating inference budget by difficulty beats uniform allocation → RL trains &quot;internalized long thinking&quot; (the o1/R1 line) → thinking length becomes an externally controllable knob. Deep water: Learn LLM Chapter 10 (post-training/RL), Chapter 9 (inference and budgets).</p><h2 id="_4-development" tabindex="-1">4. Development <a class="header-anchor" href="#_4-development" aria-label="Permalink to &quot;4. Development&quot;">​</a></h2><p><strong>Symptom → where to go</strong>:</p><ul><li>&quot;Latency variance is wild, occasional runaway responses&quot; → this section&#39;s stance: set stop conditions on thinking; the engineering landing point is circuit breakers and budgets in <a href="./../08-production/cost-performance.html">Cost and Performance</a>.</li><li>&quot;The model keeps making single-step mistakes; want it to think more&quot; → classify the error first: closed-form reasoning → reasoning model / higher thinking budget; missing facts → <a href="./../04-grounding/">04-grounding</a>; needs execution → <a href="./../05-action/tool-calling.html">05-action</a>.</li><li>&quot;The agent maxes out thinking at every step and costs explode&quot; → tiered budgets: high for planning steps, low for execution steps — landing in <a href="./../06-agent-systems/agent-runtime.html">06-agent-systems</a> runtime config.</li><li>Want to understand how RL produces reasoning behavior → Learn LLM Chapter 10.</li></ul><h2 id="_5-resource-library" tabindex="-1">5. Resource Library <a class="header-anchor" href="#_5-resource-library" aria-label="Permalink to &quot;5. Resource Library&quot;">​</a></h2><p>Primary sources (identifiers only; no content re-narrated):</p><table tabindex="0"><thead><tr><th>Name</th><th>Origin</th><th>Identifier</th></tr></thead><tbody><tr><td>Large Language Monkeys (repeated-sampling scaling)</td><td>Stanford / Google DeepMind</td><td>arXiv:2407.21787</td></tr><tr><td>Scaling LLM Test-Time Compute Optimally</td><td>UC Berkeley / Google DeepMind</td><td>arXiv:2408.03314</td></tr><tr><td>DeepSeek-R1 (reasoning via pure RL)</td><td>DeepSeek-AI</td><td>arXiv:2501.12948</td></tr><tr><td>s1: Simple test-time scaling (budget forcing)</td><td>Stanford / UW et al.</td><td>arXiv:2501.19393</td></tr></tbody></table><p>(retrievedAt 2026-09-01; current parameters and pricing of each vendor&#39;s reasoning models follow their official docs in real time.)</p><h3 id="where-learn-ai-stops-where-to-go-next" tabindex="-1">Where learn-ai stops / where to go next <a class="header-anchor" href="#where-learn-ai-stops-where-to-go-next" aria-label="Permalink to &quot;Where learn-ai stops / where to go next&quot;">​</a></h3><ul><li>Long-CoT RL, GRPO, inference scaling laws: <a href="https://llm.zenheart.site/" target="_blank" rel="noreferrer">Learn LLM</a> Chapter 10 (Post-training).</li><li>Engineering closure for inference budgets and latency: <a href="./../08-production/cost-performance.html">Cost and Performance</a>, <a href="./../08-production/deployment.html">Deployment and Release</a>.</li></ul>',25)])])}const b=t(a,[["render",r]]);export{f as __pageData,b as default};
